def policy(obs, P):
    x = obs[0]
    cv = obs[1]
    pa = obs[2]
    pav = obs[3]
    if cv > P["cv_high"]:
        return 0
    if cv <= P["cv_low"]:
        if x <= P["x_thr"]:
            if pav > P["pav_thr1"]:
                return 1
            return 0
        else:
            if cv < P["cv_vlow"] and pav > P["pav_vhigh"]:
                return 1
            return 0
    if pa <= P["pa_low"]:
        return 0
    if pav <= P["pav_low"]:
        if pa > P["pa_high"]:
            return 0
        return 1
    else:
        if pa > P["pa_high2"] and pav > P["pav_high"]:
            return 0
        return 1
